// IFC viewer: web-ifc parses the model, three.js draws it.
// Two models: the pumping station (from the organisers) and the sewer network (generated by pipeline/build_ifc.py).
// Click an element to see its IFC type, name and the property sets that link it to Maximo, W-OTL and the decision model.
import * as WebIFC from 'https://cdn.jsdelivr.net/npm/web-ifc@0.0.66/web-ifc-api.js';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

export const MODELS = {
  station: { url: 'data/station.ifc', title: 'Pumping station Jan de Jonghstraat', size: '25 MB',
    intro: n => `<b>Eindgemaal Jan de Jonghstraat</b> · IFC 4.3 from the organisers · ${n} elements. Click an element to see its Maximo asset code and W-OTL identifier.`,
    psets: /maximo|otl|Environmental/i, view: [0.9, 0.7, 0.9] },
  sewer: { url: 'data/sewer_x4.ifc', title: 'Sewer network in 3D (pipes drawn ×4 thicker)', size: '11 MB', advice: true,
    intro: n => `<b>Sewer network</b> · IFC 4.3 generated from the GIS graph · ${n} elements at real depth (m NAP), <b>pipes drawn 4× thicker</b> for readability. Colours: <span style="color:#4f7a5e">■ defer</span> <span style="color:#c4840a">■ reline</span> <span style="color:#b0432d">■ replace</span>; grey = manholes. Soil layers from TNO GeoTOP (IfcGeotechnicalStratum): <span style="color:#73502e">■ peat</span> <span style="color:#7a8c6b">■ clay</span> <span style="color:#e6c35f">■ sand</span> <span style="color:#bdbab3">■ made ground</span>. Click a pipe or a soil layer.`,
    psets: /AGV_/i, view: [0.25, 0.35, 0.45] },
  sewerTrue: { url: 'data/sewer.ifc', title: 'Sewer network in 3D (true size)', size: '11 MB', advice: true,
    intro: n => `<b>Sewer network</b> · IFC 4.3 generated from the GIS graph · ${n} elements at real depth (m NAP). Pipes coloured by advice: <span style="color:#4f7a5e">■ defer</span> <span style="color:#c4840a">■ reline</span> <span style="color:#b0432d">■ replace</span>; grey cylinders are manholes. Soil layers from TNO GeoTOP (IfcGeotechnicalStratum). Click a pipe or a soil layer.`,
    psets: /AGV_/i, view: [0.25, 0.35, 0.45] },
};

let ifc = null, viewer = null;

async function getIfc() {
  if (!ifc) {
    ifc = new WebIFC.IfcAPI();
    ifc.SetWasmPath('https://cdn.jsdelivr.net/npm/web-ifc@0.0.66/', true);
    await ifc.Init();
  }
  return ifc;
}

function makeViewer(container) {
  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setPixelRatio(window.devicePixelRatio);
  container.appendChild(renderer.domElement);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xe9eef1);
  const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 5000);
  const controls = new OrbitControls(camera, renderer.domElement);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x8899aa, 1.6));
  const sun = new THREE.DirectionalLight(0xffffff, 1.2);
  sun.position.set(50, 80, 30);
  scene.add(sun);
  const resize = () => {
    const w = container.clientWidth, h = container.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h);
    camera.aspect = w / h; camera.updateProjectionMatrix();
  };
  new ResizeObserver(resize).observe(container);
  renderer.setAnimationLoop(() => { controls.update(); renderer.render(scene, camera); });
  return { renderer, scene, camera, controls, resize, groups: {}, current: null, onPick: null };
}

export async function showModel(container, info, key = 'station') {
  const cfg = MODELS[key];
  if (!viewer) {
    viewer = makeViewer(container);
    const ray = new THREE.Raycaster(), mouse = new THREE.Vector2();
    const highlight = new THREE.MeshLambertMaterial({ color: 0x1a73e8, side: THREE.DoubleSide });
    let picked = [];
    viewer.renderer.domElement.addEventListener('click', async e => {
      const g = viewer.groups[viewer.current];
      if (!g) return;
      const rect = viewer.renderer.domElement.getBoundingClientRect();
      // try the cursor first, then rings of offsets up to 8 px, so thin pipes are easy to hit
      let hit = null;
      outer: for (const r of [0, 3, 6, 8]) {
        for (let a = 0; a < (r ? 8 : 1); a++) {
          const ox = r * Math.cos(a * Math.PI / 4), oy = r * Math.sin(a * Math.PI / 4);
          mouse.set(((e.clientX + ox - rect.left) / rect.width) * 2 - 1, -((e.clientY + oy - rect.top) / rect.height) * 2 + 1);
          ray.setFromCamera(mouse, viewer.camera);
          const hits = ray.intersectObjects(g.group.children.filter(m => m.visible), false);
          hit = hits.find(h => !h.object.userData.soil) || (r === 0 ? hits[0] : null); // pipes win over soil layers
          if (hit) break outer;
        }
      }
      picked.forEach(([m, mat]) => { m.material = mat; });
      picked = [];
      if (!hit) { info.innerHTML = g.intro; return; }
      const id = hit.object.userData.expressID;
      g.group.children.filter(m => m.userData.expressID === id).forEach(m => { picked.push([m, m.material]); m.material = highlight; });
      info.innerHTML = await describe(g.modelID, id, MODELS[viewer.current].psets);
    });
  }
  viewer.resize();
  Object.entries(viewer.groups).forEach(([k, g]) => { g.group.visible = k === key; });
  viewer.current = key;
  if (!viewer.groups[key]) {
    info.textContent = `Loading ${cfg.title} (${cfg.size})…`;
    // one load per model, even when the user switches back and forth while it is still loading
    viewer.loading ??= {};
    viewer.loading[key] ??= (async () => {
      const api = await getIfc();
      const buf = new Uint8Array(await (await fetch(cfg.url)).arrayBuffer());
      const modelID = api.OpenModel(buf, { COORDINATE_TO_ORIGIN: true });
      const colourOf = cfg.advice ? adviceColours(api, modelID) : null;
      const { group, count } = buildGroup(api, modelID, colourOf);
      viewer.scene.add(group);
      const soil = cfg.advice ? soilIds(api, modelID) : new Map();
      const soilMats = {};
      group.children.forEach(m => {
        const name = soil.get(m.userData.expressID);
        if (name !== undefined) { m.userData.soil = true; m.material = (soilMats[name] ||= soilMaterial(name)); m.renderOrder = 1; }
        else if (cfg.advice) m.renderOrder = 0;
      });
      viewer.groups[key] = { group, modelID, intro: cfg.intro(count.toLocaleString('en-US')), box: new THREE.Box3().setFromObject(group) };
    })();
    await viewer.loading[key];
    // a model that finishes loading after the user switched away stays hidden
    viewer.groups[key].group.visible = viewer.current === key;
    if (viewer.current !== key) return;
  }
  const g = viewer.groups[key];
  frame(g.box, cfg.view);
  info.innerHTML = g.intro;
}

function frame(box, dir) {
  const size = box.getSize(new THREE.Vector3()), center = box.getCenter(new THREE.Vector3());
  const r = Math.max(size.x, size.y, size.z);
  const { camera, controls } = viewer;
  camera.position.copy(center).add(new THREE.Vector3(r * dir[0], r * dir[1], r * dir[2]));
  camera.near = r / 2000; camera.far = r * 20; camera.updateProjectionMatrix();
  controls.target.copy(center);
  controls.update();
}

// Colour pipes by the advice stored in their Description ("… · advice: replace"), manholes grey.
const ADVICE_RGB = { defer: 0x4f7a5e, reline: 0xd4900f, replace: 0xc0442c };
function adviceColours(api, modelID) {
  const map = new Map();
  const ids = api.GetLineIDsWithType(modelID, WebIFC.IFCPIPESEGMENT);
  for (let i = 0; i < ids.size(); i++) {
    const line = api.GetLine(modelID, ids.get(i));
    const a = /advice: (\w+)/.exec(line.Description?.value || '')?.[1];
    if (a) map.set(ids.get(i), ADVICE_RGB[a]);
  }
  return id => map.get(id) ?? null; // manholes and soil layers keep their IFC colour
}

// soil layers: expressID -> lithoclass name (IfcGeotechnicalStratum.Name)
function soilIds(api, modelID) {
  const map = new Map();
  if (WebIFC.IFCGEOTECHNICALSTRATUM === undefined) return map;
  const ids = api.GetLineIDsWithType(modelID, WebIFC.IFCGEOTECHNICALSTRATUM);
  for (let i = 0; i < ids.size(); i++) map.set(ids.get(i), api.GetLine(modelID, ids.get(i)).Name?.value || '');
  return map;
}
// web-ifc does not pass IFC transparency through, so set it here per lithoclass
const SOIL_LOOK = { 'made ground (fill)': [0xcfcbc3, 0.05], peat: [0x73502e, 0.55], clay: [0x7a8c6b, 0.35], 'clayey sand / loam': [0x9e996f, 0.3] };
const soilMaterial = name => {
  const [col, op] = SOIL_LOOK[name] || [0xe6c35f, 0.22]; // sands and the rest
  return new THREE.MeshLambertMaterial({ color: col, transparent: true, opacity: op, depthWrite: false, side: THREE.DoubleSide });
};

export function setSoil(on) {
  Object.values(viewer?.groups || {}).forEach(g => g.group.children.forEach(m => { if (m.userData.soil) m.visible = on; }));
}

function buildGroup(api, modelID, colourOf) {
  const group = new THREE.Group();
  const materials = new Map();
  let count = 0;
  api.StreamAllMeshes(modelID, flatMesh => {
    const placed = flatMesh.geometries;
    for (let i = 0; i < placed.size(); i++) {
      const pg = placed.get(i);
      const g = api.GetGeometry(modelID, pg.geometryExpressID);
      const verts = api.GetVertexArray(g.GetVertexData(), g.GetVertexDataSize());
      const index = api.GetIndexArray(g.GetIndexData(), g.GetIndexDataSize());
      const pos = new Float32Array(verts.length / 2), nor = new Float32Array(verts.length / 2);
      for (let v = 0, j = 0; v < verts.length; v += 6, j += 3) {
        pos[j] = verts[v]; pos[j + 1] = verts[v + 1]; pos[j + 2] = verts[v + 2];
        nor[j] = verts[v + 3]; nor[j + 1] = verts[v + 4]; nor[j + 2] = verts[v + 5];
      }
      const geom = new THREE.BufferGeometry();
      geom.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      geom.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
      geom.setIndex(new THREE.BufferAttribute(index, 1));
      const c = pg.color, hex = colourOf ? colourOf(flatMesh.expressID) : null;
      const key = hex ?? `${c.x},${c.y},${c.z},${c.w}`;
      if (!materials.has(key)) {
        materials.set(key, hex != null
          ? new THREE.MeshLambertMaterial({ color: hex, side: THREE.DoubleSide })
          : new THREE.MeshLambertMaterial({ color: new THREE.Color(c.x, c.y, c.z), transparent: c.w < 1, opacity: c.w, depthWrite: c.w >= 1, side: THREE.DoubleSide }));
      }
      const mesh = new THREE.Mesh(geom, materials.get(key));
      mesh.matrixAutoUpdate = false;
      mesh.matrix.fromArray(pg.flatTransformation);
      mesh.userData.expressID = flatMesh.expressID;
      group.add(mesh);
      g.delete();
    }
    count++;
  });
  return { group, count };
}

async function describe(modelID, id, filter) {
  const line = ifc.GetLine(modelID, id);
  const type = ifc.GetNameFromTypeCode ? ifc.GetNameFromTypeCode(line.type) : '';
  const name = line.Name?.value || '(no name)';
  const desc = line.Description?.value ? ` · ${line.Description.value}` : '';
  let psets = [];
  try { psets = await ifc.properties.getPropertySets(modelID, id, true); } catch { /* ignore */ }
  const rows = [];
  for (const ps of psets || []) {
    const psName = ps.Name?.value || '';
    if (!filter.test(psName)) continue;
    for (const pr of ps.HasProperties || []) {
      rows.push(`<tr><td>${psName}</td><td>${pr.Name?.value ?? ''}</td><td>${pr.NominalValue?.value ?? ''}</td></tr>`);
    }
  }
  return `<b>${type}</b> · ${name}${desc} <span class="muted">(#${id})</span>` +
    (rows.length ? `<table><thead><tr><th>Property set</th><th>Property</th><th>Value</th></tr></thead><tbody>${rows.join('')}</tbody></table>`
      : '<div class="muted">No linked property sets on this element.</div>');
}
